def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n >= 99:
        return 'D'

    my_actions = [h[0] for h in history]
    opp_actions = [h[1] for h in history]

    first_my_defect = -1
    for i, a in enumerate(my_actions):
        if a == 'D':
            first_my_defect = i
            break

    if first_my_defect == -1:
        if any(a == 'D' for a in opp_actions):
            return 'D'
        if n == 5:
            return 'D'
        return 'C'

    is_probe = (first_my_defect == 5)
    if is_probe:
        for i in range(first_my_defect):
            if opp_actions[i] == 'D':
                is_probe = False
                break

    if is_probe:
        retaliation_idx = -1
        if opp_actions[first_my_defect] == 'D':
            retaliation_idx = first_my_defect
        else:
            for i in range(first_my_defect + 1, n):
                if opp_actions[i] == 'D':
                    retaliation_idx = i
                    break

        if retaliation_idx == -1:
            if n == first_my_defect + 1:
                return 'C'
            return 'D'
        else:
            if n <= retaliation_idx + 5:
                return 'C'
            if opp_actions[-1] == 'D':
                return 'D'
            return 'C'
    else:
        if opp_actions[-1] == 'D':
            return 'D'
        return 'C'
